const styles=new CSSStyleSheet;styles.replaceSync('/*\n * Copyright 2017 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n.widget.ax-subpane {\n  overflow-x: hidden;\n  user-select: text;\n}\n\n.ax-ignored-info {\n  padding: 6px;\n}\n\n.ax-ignored-node-pane {\n  flex: none;\n}\n\n.invalid {\n  text-decoration: line-through;\n}\n\nspan.ax-value-undefined {\n  font-style: italic;\n}\n\n.ax-value-source-unused {\n  opacity: 70%;\n}\n\n.ax-value-source-superseded,\n.ax-value-source-invalid {\n  text-decoration: line-through;\n}\n\n.tree-outline span[is="dt-icon-label"] {\n  position: relative;\n  left: -11px;\n}\n\n.tree-outline li {\n  display: block;\n  overflow-x: hidden;\n  align-items: baseline;\n}\n\n.tree-outline li::before {\n  content: "";\n  width: 14px;\n  display: inline-block;\n  margin-bottom: -2px;\n  margin-right: 3px;\n}\n\n.tree-outline li.property {\n  color: var(--color-text-primary);\n}\n\n.tree-outline li.invalid {\n  position: relative;\n  left: -2px;\n}\n\n.tree-outline span[is="dt-icon-label"] + .ax-name {\n  margin-left: -11px;\n}\n\n.tree-outline li span {\n  flex-shrink: 0;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n@media (forced-colors: active) {\n  .ax-value-source-unused {\n    opacity: 100%;\n  }\n\n  .tree-outline-disclosure:hover li.parent::before {\n    background-color: ButtonText;\n  }\n}\n\n/*# sourceURL=accessibilityNode.css */\n');export default styles;